-- =====================================================================
-- CASA DEL TERROR  |  02 - DML (datos de prueba)
-- Ejecutar DESPUES de 01_ddl_casa_terror.sql, con "Ejecutar script" (F5).
--
-- * Las fechas son RELATIVAS a SYSDATE (hoy +/- N dias): asi las sesiones
--   futuras siempre quedan en el futuro cuando vuelvas a cargar los datos.
-- * Los datos respetan TODAS las reglas del negocio (ver 03_auditoria_reglas.sql).
-- * Archivo solo ASCII: las tildes van con UNISTR('\00XX').
-- * Se insertan los IDs de forma explicita y al final se sincronizan las
--   columnas IDENTITY, igual que en el ejemplo de la profesora.
-- =====================================================================

SET DEFINE OFF;

-- ---------------------------------------------------------------- TIPO_EXPERIENCIA

-- ---------------------------------------------------------------- CLIENTE
-- La fila 1 es el VISITANTE GENERAL: nunca se borra y siempre esta ACTIVO.

-- ---------------------------------------------------------------- EXPERIENCIA

-- ---------------------------------------------------------------- SESION
-- Cada sesion pertenece a una experiencia (s_id_experiencias) y se realiza en su zona.
-- Los cupos disponibles se calculan al final con un UPDATE (ver mas abajo).

-- ---------------------------------------------------------------- VENTA (hechos)

-- ---------------------------------------------------------------- SINCRONIZACION
-- Cupos disponibles = cupos totales - personas de las ventas que NO estan
-- canceladas (las canceladas devuelven sus cupos).
UPDATE sesion s
SET s.s_cupos_disponibles = s.s_cupos_totales - NVL((
        SELECT SUM(v.v_cantidad_personas) FROM venta v
        WHERE v.v_id_sesiones = s.s_id_sesiones AND v.v_estado <> 'CANCELADA'), 0);

-- Las columnas IDENTITY continuan despues del maximo ID insertado.
ALTER TABLE tipo_experiencia MODIFY te_id_tipos_experiencia GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE cliente          MODIFY c_id_clientes           GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE experiencia      MODIFY ex_id_experiencias      GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE sesion           MODIFY s_id_sesiones           GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE venta            MODIFY v_id_ventas             GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);

COMMIT;

-- Conteo de control
SELECT 'TIPO_EXPERIENCIA' AS tabla, COUNT(*) AS filas FROM tipo_experiencia
UNION ALL SELECT 'CLIENTE', COUNT(*) FROM cliente
UNION ALL SELECT 'EXPERIENCIA', COUNT(*) FROM experiencia
UNION ALL SELECT 'SESION', COUNT(*) FROM sesion
UNION ALL SELECT 'VENTA', COUNT(*) FROM venta;
